import heapq

def kth_largest_element_in_a_stream(k, nums, vals):
    heap = list(nums)
    heapq.heapify(heap)
    while len(heap) > k:
        heapq.heappop(heap)

    def add(val):
        heapq.heappush(heap, val)
        if len(heap) > k:
            heapq.heappop(heap)
        return heap[0]

    return [add(v) for v in vals]

